n":"LATEX_PRESENTATION","lhs_symbols":["S-ECI"],"rhs_symbols":["S-PI","S-CI","S-DI","S-RI"],"equation_type":"OBJECTIVE","unit":"dimensionless","depends_on":[],"source":"R-Q3","shared":false,"e1_span":"对每个节点，枚举检测/不检测、拆解/不拆解的组合，选择期望成本最小的方案"}},{"kind":"EquationSpec","value":{"equation_id":"E-Q4-PHAT","scope_ref":"P4","expression":"phat = (X+1)/(n+2)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PHAT"],"rhs_symbols":["S-X","S-N"],"equation_type":"DERIVED","unit":"dimensionless","depends_on":[],"source":"R-Q4","shared":false,"e1_span":"可用其均值 p̂ = (X+1)/(n+2) 作为点估计代入原模型"}},{"kind":"EquationSpec","value":{"equation_id":"E-Q4-EC","scope_ref":"P4","expression":"EC4 = ∫ E[C | p] f(p) dp","representation":"LATEX_PRESENTATION","lhs_symbols":["S-EC4"],"rhs_symbols":["S-PHAT"],"equation_type":"OBJECTIVE","unit":"dimensionless","depends_on":["E-Q4-PHAT"],"source":"R-Q4","shared":false,"e1_span":"E[C] = ∫ E[C | p] f(p) dp"}},{"kind":"ModelSpec","value":{"model_id":"M1","problem_refs":["P1"],"assumption_refs":["A-BINOMIAL-SAMPLING","A-INDEPENDENT-PARTS"],"variable_refs":["S-N","S-C","S-X"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.1}],"equation_refs":["E-Q1-ACCEPT","E-Q1-REJECT"],"constraints":["P(X > c | p = p0) <= 0.05","P(X <= c | p = p0) >= 0.90"],"objective":"minimize n","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M2","problem_refs":["P2"],"assumption_refs":["A-CONSTANT-RATES","A-REPAIR-NO-DAMAGE","A-REPLACEMENT-COST","A-EXPECTED-VALUE-CRITERION","A-INFINITE-HORIZON","A-INDEPENDENT-PARTS"],"variable_refs":["S-X1","S-X2","S-XF","S-XR","S-XU","S-EC"],"parameter_refs":[{"symbol_ref":"S-P1","value":0.1},{"symbol_ref":"S-P2","value":0.1},{"symbol_ref":"S-PF","value":0.1},{"symbol_ref":"S-C1","value":4},{"symbol_ref":"S-C2","value":4},{"symbol_ref":"S-D1","value":1},{"symbol_ref":"S-D2","value":1},{"symbol_ref":"S-A","value":2},{"symbol_ref":"S-DF","value":1},{"symbol_ref":"S-S","value":20},{"symbol_ref":"S-L","value":5},{"symbol_ref":"S-R","value":1}],"equation_refs":["E-Q2-EC"],"constraints":["x1 ∈ {0,1}","x2 ∈ {0,1}","xf ∈ {0,1}","xr ∈ {0,1}","xu ∈ {0,1}"],"objective":"minimize EC","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M3","problem_refs":["P3"],"assumption_refs":["A-CONSTANT-RATES","A-REPAIR-NO-DAMAGE","A-REPLACEMENT-COST","A-EXPECTED-VALUE-CRITERION","A-INFINITE-HORIZON","A-INDEPENDENT-PARTS"],"variable_refs":["S-ECI"],"parameter_refs":[{"symbol_ref":"S-PI","value":0.1},{"symbol_ref":"S-CI","value":4},{"symbol_ref":"S-DI","value":1},{"symbol_ref":"S-RI","value":1}],"equation_refs":["E-Q3-REC"],"constraints":["决策变量为二元选择"],"objective":"minimize ECi at each node","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M4","problem_refs":["P4"],"assumption_refs":["A-SAMPLING-ESTIMATE-UNCERTAINTY","A-EXPECTED-VALUE-CRITERION","A-CONSTANT-RATES","A-REPAIR-NO-DAMAGE","A-REPLACEMENT-COST","A-INFINITE-HORIZON","A-INDEPENDENT-PARTS"],"variable_refs":["S-PHAT","S-EC4"],"parameter_refs":[{"symbol_ref":"S-X","value":12},{"symbol_ref":"S-N","value":82}],"equation_refs":["E-Q4-PHAT","E-Q4-EC"],"constraints":["后验分布为 Beta(X+1, n-X+1)"],"objective":"minimize EC4","dependencies":["M2","M3"]}}],"code":"const fs = require('fs');
function binomCdf(k, n, p) {
  let s = 0;
  let term = Math.pow(1 - p, n);
  for (let i = 0; i <= k; i++) {
    s += term;
    term *= (n - i) / (i + 1) * p / (1 - p);
  }
  return s;
}
function binomSf(k, n, p) {
  return 1 - binomCdf(k - 1, n, p);
}
let n = 1, c = 0;
while (true) {
  let found = false;
  for (let cc = 0; cc <= n; cc++) {
    const reject = binomSf(cc + 1, n, 0.1);
    const accept = binomCdf(cc, n, 0.1);
    if (reject <= 0.05 && accept >= 0.90) {
      n = n; c = cc; found = true; break;
    }
  }
  if (found) break;
  n++;
}
const phat = (12 + 1) / (82 + 2);
const out = {
  n_fixed: n,
  c_fixed: c,
  p_accept: binomCdf(c, n, 0.1),
  p_reject: binomSf(c + 1, n, 0.1),
  phat: phat,
  ec4: phat * 20 + (1 - phat) * 5
};
