","scope_ref":"P3","expression":"ECi = min over decisions of expected cost at node i","representation":"LATEX_PRESENTATION","lhs_symbols":["S-ECI"],"rhs_symbols":["S-PI","S-CI","S-DI","S-RI"],"equation_type":"OBJECTIVE","unit":"dimensionless","depends_on":[],"source":"E1","shared":false,"e1_span":"对每个节点，枚举检测/不检测、拆解/不拆解的组合，选择期望成本最小的方案"}},{"kind":"EquationSpec","value":{"equation_id":"E-Q4-EC","scope_ref":"P4","expression":"E[C] = ∫ E[C | p] f(p) dp","representation":"LATEX_PRESENTATION","lhs_symbols":["S-EC4"],"rhs_symbols":["S-PHAT"],"equation_type":"OBJECTIVE","unit":"dimensionless","depends_on":[],"source":"E1","shared":false,"e1_span":"E[C] = ∫ E[C | p] f(p) dp"}},{"kind":"EquationSpec","value":{"equation_id":"E-Q4-PHAT","scope_ref":"P4","expression":"phat = (X+1)/(n+2)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PHAT"],"rhs_symbols":["S-X","S-N"],"equation_type":"DERIVED","unit":"dimensionless","depends_on":[],"source":"E1","shared":false,"e1_span":"p̂ = (X+1)/(n+2)"}},{"kind":"ModelSpec","value":{"model_id":"M1","problem_refs":["P1"],"assumption_refs":["A-INDEPENDENT-PARTS","A-BINOMIAL-SAMPLING"],"variable_refs":["S-N","S-C","S-X"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.1}],"equation_refs":["E-Q1-REJECT","E-Q1-ACCEPT"],"constraints":["P(X > c | p = p0) <= 0.05","P(X <= c | p = p0) >= 0.90"],"objective":"minimize n","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M2","problem_refs":["P2"],"assumption_refs":["A-INDEPENDENT-PARTS","A-CONSTANT-RATES","A-REPAIR-NO-DAMAGE","A-REPLACEMENT-COST","A-EXPECTED-VALUE-CRITERION","A-INFINITE-HORIZON"],"variable_refs":["S-X1","S-X2","S-XF","S-XR","S-XU","S-EC"],"parameter_refs":[{"symbol_ref":"S-P1","value":0.1},{"symbol_ref":"S-P2","value":0.1},{"symbol_ref":"S-PF","value":0.1},{"symbol_ref":"S-C1","value":1},{"symbol_ref":"S-C2","value":1},{"symbol_ref":"S-D1","value":0.1},{"symbol_ref":"S-D2","value":0.1},{"symbol_ref":"S-A","value":1},{"symbol_ref":"S-DF","value":0.1},{"symbol_ref":"S-S","value":10},{"symbol_ref":"S-L","value":1},{"symbol_ref":"S-R","value":0.5}],"equation_refs":["E-Q2-EC"],"constraints":[],"objective":"minimize E[C]","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M3","problem_refs":["P3"],"assumption_refs":["A-INDEPENDENT-PARTS","A-CONSTANT-RATES","A-REPAIR-NO-DAMAGE","A-REPLACEMENT-COST","A-EXPECTED-VALUE-CRITERION","A-INFINITE-HORIZON"],"variable_refs":["S-ECI"],"parameter_refs":[{"symbol_ref":"S-PI","value":0.1},{"symbol_ref":"S-CI","value":1},{"symbol_ref":"S-DI","value":0.1},{"symbol_ref":"S-RI","value":0.5}],"equation_refs":["E-Q3-REC"],"constraints":[],"objective":"minimize ECi at each node","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M4","problem_refs":["P4"],"assumption_refs":["A-SAMPLING-ESTIMATE-UNCERTAINTY","A-EXPECTED-VALUE-CRITERION"],"variable_refs":["S-PHAT","S-EC4"],"parameter_refs":[],"equation_refs":["E-Q4-EC","E-Q4-PHAT"],"constraints":[],"objective":"minimize E[C] under uncertainty","dependencies":[]}}],"code":"const fs = require('fs');
function binomCdf(k, n, p) {
  let c = 0;
  let term = Math.pow(1 - p, n);
  for (let i = 0; i <= k; i++) {
    c += term;
    term *= (n - i) / (i + 1) * p / (1 - p);
  }
  return c;
}
function findMinN() {
  const p0 = 0.1;
  for (let n = 1; n <= 200; n++) {
    for (let c = 0; c < n; c++) {
      const pReject = 1 - binomCdf(c, n, p0);
      const pAccept = binomCdf(c, n, p0);
      if (pReject <= 0.05 && pAccept >= 0.90) {
        return { n, c, pAccept, pReject };
      }
    }
  }
  return null;
}
const q1 = findMinN();
const out = {
