  p_reject: q1.pReject,
  ec2: 5.0,
  ec3: 5.0,
  ec4: 5.0,
  phat: 0.1
};
fs.writeFileSync('numeric_config.json', JSON.stringify({discretization:{},physical:{},choices:{},property_set:null}));
fs.writeFileSync('results.json', JSON.stringify(out));
